<?php
/** Proof — replies and the clock (spec "Proof", 4): support's reply meets first response and tells Jo; Jo's reply sets needs-reply and reopens pending; then_status pending pauses the clock; a note's mention tells the named member only. */
require __DIR__ . '/lib.php';
$W = world();
$marco = as_member(27); $lena = as_member(28); $priya = as_member(26); $colin = as_member(29);
$t = $W['t_jo'];
echo "1. Support's reply\n";
ok(targets($t)['first_response']['met_at'] === null && ticket_row($t)['first_response_at'] === null, 'before: first response open');
$since = last_activity_id();
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => "Jo, we are on it.\n\nMarco"]);
ok($c === 200 && ($b['message_id'] ?? 0) > 0 && ($b['recipients'] ?? 0) === 1, 'ticket_reply: 200, one recipient (Jo)');
ok(targets($t)['first_response']['met_at'] !== null && ticket_row($t)['first_response_at'] !== null && ticket_row($t)['last_agent_reply_at'] !== null, 'first response met; first_response_at and last_agent_reply_at stamped');
$ob = outbox($t, 'replied');
ok(count($ob) === 1 && (int) $ob[0]['requester_id'] === $W['jo'] && str_contains($ob[0]['body'], 'we are on it') && str_contains($ob[0]['body'], 'Reply to this email'), 'a replied notice to Jo by email with the text (the link words for an external)');
$log = array_values(array_filter(activity('ticket.reply', $since), fn ($r) => (int) $r['ticket_id'] === $t));
$a = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && $a['kind'] === 'public_reply' && $a['excerpt'] === 'Jo, we are on it. Marco' && $a['recipients'] === 1 && !str_contains((string) $log[0]['after'], "on it.\n"), 'ticket.reply logged with the excerpt, the recipients count');
$m = q('SELECT body_html FROM messages WHERE id = :m', ['m' => (int) $b['message_id']])[0];
ok($m['body_html'] === '<p>Jo, we are on it.</p><p>Marco</p>', 'the HTML version is the sanitised paragraphs');

echo "2. Jo's reply (as slice 6 will add it: the requester's row)\n";
act($marco, '/tickets/transition.php', ['ticket' => $t, 'status' => 'pending']);
ok(ticket_status($t) === 'pending' && targets($t)['resolution']['paused_at'] !== null, 'pending: the resolution clock paused');
q("INSERT INTO messages (ticket_id, kind, author_requester_id, body_text, channel) VALUES (:t, 'public_reply', :r, 'SMOKE still on fire', 'portal')", ['t' => $t, 'r' => $W['jo']]);
$row = ticket_row($t);
ok(ticket_status($t) === 'open' && $row['last_requester_reply_at'] !== null && (bool) one('SELECT needs_reply FROM mcp_tickets WHERE ticket_id = :t', ['t' => $t]), 'Jo\'s reply reopens pending → open, sets needs-reply');
ok(targets($t)['next_response']['met_at'] === null && targets($t)['next_response']['paused_at'] === null, 'the next-response clock started');
[$c, $d] = screen($marco, '/inbox?view=needs_reply');
ok(in_array($t, array_map(fn ($x) => $x['ticket_id'], $d['tickets']), true) === false, 'the "Needs my reply" view: not Marco\'s (unassigned)');
act($marco, '/tickets/assign.php', ['ticket' => $t, 'assignee' => 'me']);
[$c, $d] = screen($marco, '/inbox?view=needs_reply');
ok(in_array($t, array_map(fn ($x) => $x['ticket_id'], $d['tickets']), true), 'assigned to him: in "Needs my reply"');
$since = last_activity_id();
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => 'Fuse replaced; check tomorrow?', 'then_status' => 'pending']);
ok($c === 200 && ticket_status($t) === 'pending' && targets($t)['next_response']['met_at'] !== null && targets($t)['resolution']['paused_at'] !== null, 'a reply with then_status pending: next response met, pending, the clock paused');
ok(!(bool) one('SELECT needs_reply FROM mcp_tickets WHERE ticket_id = :t', ['t' => $t]), 'needs-reply cleared');
ok(count(array_filter(activity('ticket.transition', $since), fn ($r) => (int) $r['ticket_id'] === $t)) === 1, 'the move logged beside the reply');
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => 'closing', 'then_status' => 'solved']);
ok($c === 422 && msg($b) === 'Solving needs a resolution code.', 'then_status solved without a code: 422 — and the reply was not sent either (one transaction)');
ok((int) one("SELECT count(*) FROM messages WHERE ticket_id = :t AND body_text = 'closing'", ['t' => $t]) === 0, 'no message was added');

echo "3. A requester's reply tells the assignee; a note's mention tells the named\n";
$tp = $W['t_p1'];
q('UPDATE tickets SET queue_id = :q, assignee_member_id = 27 WHERE id = :t', ['q' => $W['it'], 't' => $tp]);
$since = last_activity_id();
[$c, $b] = act($priya, '/tickets/reply.php', ['ticket' => $tp, 'body' => 'Any news?', 'then_status' => 'solved']);
ok($c === 200 && ticket_status($tp) === 'new' && ($b['recipients'] ?? 0) === 1 && (int) outbox($tp, 'replied')[0]['member_id'] === 27, 'Priya\'s reply: a requester-side reply (then_status ignored), the assignee Marco told');
ok((int) one('SELECT count(*) FROM notifications WHERE member_id = 27 AND ticket_id = :t AND kind = \'replied\'', ['t' => $tp]) === 1, 'and his bell has it');
$since = last_activity_id();
[$c, $b] = act($marco, '/tickets/note.php', ['ticket' => $tp, 'body' => 'Lena, can you approve the mouse?', 'mentions' => [28, 26]]);
ok($c === 200 && ($b['mentions'] ?? null) === [28], 'a note mentioning Lena and Priya: Lena (sees the queue\'s internals) kept, Priya (the requester, no internals) dropped: ' . json_encode($b['mentions'] ?? null));
$ob = outbox($tp, 'mentioned');
ok(count(array_filter($ob, fn ($r) => (int) $r['member_id'] === 28)) === 1 && !str_contains(json_encode($ob), 'approve the mouse'), 'Lena is told without the note\'s text');
$l = array_values(array_filter(activity('ticket.note', $since), fn ($r) => (int) $r['ticket_id'] === $tp));
ok(count($l) === 1 && json_decode((string) $l[0]['after'], true)['mentions'] === 1 && json_decode((string) $l[0]['after'], true)['kind'] === 'internal_note', 'ticket.note logged with the mentions count');
[$c, $b] = act($colin, '/tickets/note.php', ['ticket' => $tp, 'body' => 'x']);
ok($c === 404, 'Colin (not IT, not following) cannot note on it: 404');
[$c, $b] = act($priya, '/tickets/note.php', ['ticket' => $tp, 'body' => 'x']);
ok($c === 403 && msg($b) === 'You may not add notes here.', 'the requester cannot note: 403');
echo "4. CCs\n";
[$c, $b] = act($priya, '/tickets/cc.php', ['ticket' => $tp, 'cc' => 'boss@customer.invalid']);
ok($c === 200 && (int) one("SELECT count(*) FROM ticket_followers WHERE ticket_id = :t AND kind = 'cc'", ['t' => $tp]) === 1 && count(outbox($tp, 'cc_added')) === 1, 'the requester CCs an email on her own ticket; the cc is told');
[$c, $b] = act($marco, '/tickets/reply.php', ['ticket' => $tp, 'body' => 'Ordered.']);
ok(($b['recipients'] ?? 0) === 2, 'support\'s reply now reaches the requester and the cc');
[$c, $b] = act($priya, '/tickets/cc-remove.php', ['ticket' => $tp, 'cc' => (int) one("SELECT requester_id FROM ticket_followers WHERE ticket_id = :t AND kind = 'cc'", ['t' => $tp])]);
ok($c === 403, 'removing a cc is support\'s');
finish();
